# 重构方案：从布尔开关到组合式复合组件

## 一、先诊断：这 5 个布尔其实是三类不同的问题

```tsx
<Composer isThread isEditing={false} showAttachments showEmoji={!isDM} hideSendButton={isReadonly} onSubmit={send} />
```

| 类型 | Props | 问题 |
|---|---|---|
| **模式开关** | `isThread`、`isEditing` | 一个布尔暗中改变组件的多处行为/布局，内部必然长满 `if` 分支 |
| **存在性开关** | `showAttachments`、`showEmoji` | "要不要渲染某个功能"不该是 prop，而该是"渲染不渲染那个子组件" |
| **否定开关** | `hideSendButton` | 双重否定（`hideSendButton={isReadonly}`），且 `showEmoji={!isDM}` 把调用方逻辑泄漏进 props |

5 个布尔 = 32 种组合，绝大多数非法且组件无法约束；新增功能只能继续加布尔，所有调用点都要改。

**对应策略**：模式开关 → 显式变体组件；存在性开关 → 组合（写不写该子组件）；否定开关 → 干脆不渲染。

## 二、重构后的调用端 API（先看使用方式）

```tsx
// 场景 1：线程回复（原 isThread + showAttachments + showEmoji）
<ThreadComposer parent={parentMessage} onSubmit={send} />

// 场景 2：DM（原 showEmoji={!isDM} —— 不想要表情，直接不写这个子组件）
<Composer onSubmit={send}>
  <Composer.Input placeholder="发送私信…" />
  <Composer.Toolbar>
    <Composer.Attachments />
  </Composer.Toolbar>
  <Composer.Submit>发送</Composer.Submit>
</Composer>

// 场景 3：编辑消息（原 isEditing）
<EditComposer message={message} onSubmit={saveEdit} onCancel={closeEditor} />

// 场景 4：只读（原 hideSendButton={isReadonly}）
// 只读 = 根本不该出现输入框，直接不渲染 Composer：
{isReadonly
  ? <MessageBody message={message} />
  : <ThreadComposer parent={parentMessage} onSubmit={send} />}
// 若确实要"能打字但不能发"，少写一个 <Composer.Submit /> 即可
```

## 三、实现

### 1. Context 接口（`composer/context.ts`）

```tsx
import { createContext, use } from 'react'

export interface Attachment {
  id: string
  name: string
  url: string
}

export interface ComposerPayload {
  text: string
  attachments: Attachment[]
}

/** 纯数据：当前状态 */
export interface ComposerState {
  draft: string
  attachments: Attachment[]
  isSubmitting: boolean
}

/** 修改状态的唯一途径 */
export interface ComposerActions {
  setDraft: (update: string | ((prev: string) => string)) => void
  addAttachments: (files: Attachment[]) => void
  removeAttachment: (id: string) => void
  submit: () => void
}

/** 派生信息：供子组件做 UI 判断，不承载行为开关 */
export interface ComposerMeta {
  canSubmit: boolean
  hasAttachments: boolean
}

/** 子组件依赖的唯一接口 */
export interface ComposerContextValue {
  state: ComposerState
  actions: ComposerActions
  meta: ComposerMeta
}

export const ComposerContext = createContext<ComposerContextValue | null>(null)

export function useComposer(): ComposerContextValue {
  const value = use(ComposerContext) // React 19；React 18 请改用 useContext(ComposerContext)
  if (value === null) {
    throw new Error('Composer 子组件必须渲染在 <Composer> 内部')
  }
  return value
}
```

### 2. 根 Provider + 子组件（`composer/Composer.tsx`）

```tsx
import { useCallback, useMemo, useRef, useState } from 'react'
import type { ComponentProps } from 'react'
import {
  ComposerContext,
  useComposer,
  type Attachment,
  type ComposerContextValue,
  type ComposerPayload,
} from './context'

/* ---------------- 根组件：唯一知道"状态如何实现"的地方 ---------------- */

export interface ComposerProps {
  children: React.ReactNode
  /** 唯一保留的行为入口：提交回调 */
  onSubmit: (payload: ComposerPayload) => void | Promise<void>
  /** 编辑等场景注入初始数据（注入的是数据，不是模式开关） */
  initialDraft?: string
  initialAttachments?: Attachment[]
}

export function Composer({
  children,
  onSubmit,
  initialDraft = '',
  initialAttachments = [],
}: ComposerProps) {
  // 状态实现细节只存在于 Provider 内。
  // 以后换成 useReducer / 外部 store，所有子组件一行都不用改。
  const [draft, setDraft] = useState(initialDraft)
  const [attachments, setAttachments] = useState<Attachment[]>(initialAttachments)
  const [isSubmitting, setIsSubmitting] = useState(false)

  const submit = useCallback(async () => {
    if (isSubmitting || (!draft.trim() && attachments.length === 0)) return
    setIsSubmitting(true)
    try {
      await onSubmit({ text: draft, attachments })
      setDraft('')
      setAttachments([])
    } finally {
      setIsSubmitting(false)
    }
  }, [draft, attachments, isSubmitting, onSubmit])

  const value = useMemo<ComposerContextValue>(
    () => ({
      state: { draft, attachments, isSubmitting },
      actions: {
        setDraft,
        addAttachments: (files) => setAttachments((prev) => [...prev, ...files]),
        removeAttachment: (id) => setAttachments((prev) => prev.filter((a) => a.id !== id)),
        submit,
      },
      meta: {
        canSubmit: !isSubmitting && (draft.trim().length > 0 || attachments.length > 0),
        hasAttachments: attachments.length > 0,
      },
    }),
    [draft, attachments, isSubmitting, submit],
  )

  return (
    <ComposerContext.Provider value={value}>
      <form
        className="composer"
        onSubmit={(event) => {
          event.preventDefault()
          void submit()
        }}
      >
        {children}
      </form>
    </ComposerContext.Provider>
  )
}

